package com.codepilot1c.core.edt.debug;
import java.util.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import com.google.gson.*;import com.codepilot1c.core.edt.development.TaskSessionService;
/** Durable compare-and-set settings changes on one live native debug target. */
public final class DebugTargetSettingsService {
 public interface Backend{Map<String,Object> snapshot(String project,String target)throws Exception;void set(String project,String target,List<String> types)throws Exception;}
 private static final Gson JSON=new GsonBuilder().serializeNulls().create();private static final Object LOCK=new Object();private final Path root;private final Backend backend;
 public DebugTargetSettingsService(Path root,Backend backend)throws Exception{this.root=root.toAbsolutePath().normalize();this.backend=backend;Files.createDirectories(this.root);if(!this.root.toRealPath().equals(this.root))throw new IllegalStateException("Settings storage moved");}
 public static DebugTargetSettingsService workspace()throws Exception{return new DebugTargetSettingsService(org.eclipse.core.resources.ResourcesPlugin.getWorkspace().getRoot().getLocation().toFile().toPath().resolve(".metadata/.plugins/com.codepilot1c.core/debug-target-settings"),new Backend(){public Map<String,Object> snapshot(String p,String t){return EdtDebugService.getInstance().debugTargetSettings(p,t);}public void set(String p,String t,List<String> types){EdtDebugService.getInstance().setDebugTargetSettings(p,t,types);}});}
 static List<String> types(Object value){if(!(value instanceof List<?> l)||l.size()>32||new HashSet<>(l).size()!=l.size()||l.stream().anyMatch(v->!(v instanceof String s)||!s.matches("[A-Z_]{1,64}")||s.equals("UNKNOWN")))throw new IllegalArgumentException("types requires unique native type names (max32)");return l.stream().map(String.class::cast).sorted().toList();}
 public Map<String,Object> preview(String project,String target,List<String> requested)throws Exception{synchronized(LOCK){var before=backend.snapshot(project,target);var after=types(requested);if(!Boolean.TRUE.equals(before.get("configurable"))||!new HashSet<>((List<?>)before.get("supported_types")).containsAll(after))throw new IllegalStateException("Target/types unavailable or shared with another project");var out=new LinkedHashMap<String,Object>();out.put("project",project);out.put("target_id",target);out.put("before",before);out.put("after_types",after);out.put("scope","selected_live_debug_target");out.put("plan_sha256",TaskSessionService.fingerprint(out));return out;}}
 private Path file(String id)throws Exception{if(!root.toRealPath().equals(root)||Files.isSymbolicLink(root))throw new IllegalStateException("Settings storage moved");if(id==null||!id.matches("dbg-settings-[a-f0-9-]{36}"))throw new IllegalArgumentException("Invalid settings_change_id");Path f=root.resolve(id+".json");if(Files.isSymbolicLink(f))throw new IllegalStateException("Linked settings receipt");return f;}
 private void save(Map<String,Object>d)throws Exception{Path f=file((String)d.get("settings_change_id"));byte[] data=JSON.toJson(d).getBytes(StandardCharsets.UTF_8);if(data.length>65536)throw new IllegalStateException("Receipt capacity");Path tmp=Files.createTempFile(root,"dbg-",".tmp");try{Files.write(tmp,data);Files.move(tmp,f,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}finally{Files.deleteIfExists(tmp);}}
 @SuppressWarnings("unchecked") public Map<String,Object> status(String id)throws Exception{synchronized(LOCK){Path f=file(id);if(!Files.isRegularFile(f,LinkOption.NOFOLLOW_LINKS)||Files.size(f)>65536)throw new IllegalStateException("Settings receipt unavailable");var d=JSON.fromJson(Files.readString(f),LinkedHashMap.class);if(!id.equals(d.get("settings_change_id")))throw new IllegalStateException("Receipt identity changed");return d;}}
 public Map<String,Object> apply(String project,String target,List<String> requested,String expected)throws Exception{synchronized(LOCK){var plan=preview(project,target,requested);if(!Objects.equals(expected,plan.get("plan_sha256")))throw new IllegalStateException("STALE_DEBUG_SETTINGS_PREVIEW");try(var paths=Files.list(root)){for(Path path:paths.filter(f->f.getFileName().toString().matches("dbg-settings-[a-f0-9-]{36}[.]json")).limit(129).toList()){var old=status(path.getFileName().toString().replace(".json",""));if(project.equals(old.get("project"))&&target.equals(old.get("target_id"))&&Set.of("apply_claimed","restore_claimed","outcome_unknown").contains(old.get("state")))throw new IllegalStateException("Inspect original settings change; unknown outcome cannot be bypassed");}}var before=TaskSessionService.object(plan.get("before"));if(types(before.get("types")).equals(types(requested)))return Map.of("changed",false,"state","unchanged");try(var paths=Files.list(root)){if(paths.limit(129).count()>128)throw new IllegalStateException("Archive reviewed settings receipts first");}var d=new LinkedHashMap<>(plan);d.put("settings_change_id","dbg-settings-"+UUID.randomUUID());d.put("state","apply_claimed");save(d);return mutate(d,types(requested),"applied");}}
 private Map<String,Object> mutate(Map<String,Object>d,List<String> desired,String state)throws Exception{try{backend.set((String)d.get("project"),(String)d.get("target_id"),desired);var current=backend.snapshot((String)d.get("project"),(String)d.get("target_id"));var before=new LinkedHashMap<>(TaskSessionService.object(d.get("before")));before.put("types",desired);if(!TaskSessionService.fingerprint(before).equals(TaskSessionService.fingerprint(current)))throw new IllegalStateException("Settings verification changed");d.put("state",state);}catch(Exception unknown){d.put("state","outcome_unknown");d.put("error_type",unknown.getClass().getSimpleName());}save(d);return d;}
 public Map<String,Object> restorePreview(String id)throws Exception{synchronized(LOCK){var d=status(id);if(!"applied".equals(d.get("state")))throw new IllegalStateException("Inspect original settings change; no replay");var current=backend.snapshot((String)d.get("project"),(String)d.get("target_id"));var after=new LinkedHashMap<>(TaskSessionService.object(d.get("before")));after.put("types",types(d.get("after_types")));if(!TaskSessionService.fingerprint(current).equals(TaskSessionService.fingerprint(after)))throw new IllegalStateException("Target or settings changed; preserve user changes");var out=new LinkedHashMap<String,Object>();out.put("settings_change_id",id);out.put("current",current);out.put("restore_types",TaskSessionService.object(d.get("before")).get("types"));out.put("plan_sha256",TaskSessionService.fingerprint(out));return out;}}
 public Map<String,Object> restore(String id,String expected)throws Exception{synchronized(LOCK){var p=restorePreview(id);if(!Objects.equals(expected,p.get("plan_sha256")))throw new IllegalStateException("STALE_DEBUG_RESTORE_PREVIEW");var d=status(id);d.put("state","restore_claimed");save(d);return mutate(d,types(p.get("restore_types")),"restored");}}
}
